34	    category: 'Bebidas',
35	  },
36	], null, 2);
37	
38	const TagBadge = ({ slug, tagsMap }) => {
39	  const t = tagsMap[slug];
40	  if (!t) return <span className="text-xs px-1.5 py-0.5 rounded font-bold bg-gray-100 dark:bg-gray-950/40 text-gray-600 dark:text-gray-400">{slug}</span>;
