43	
44	const RestauranteProdutos = () => {
45	  const navigate = useNavigate();
46	  const [produtos, setProdutos] = useState([]);
47	  const [categorias, setCategorias] = useState([]);
48	  const [categoriasGlobais, setCategoriasGlobais] = useState([]);
