50	  const [impressoras, setImpressoras] = useState([]);
51	  const tipoRestaurante = useTipoRestaurante();
52	  const [novaCategoria, setNovaCategoria] = useState('');
53	  const [criandoCateg, setCriandoCateg] = useState(false);
54	  const [deletandoCateg, setDeletandoCateg] = useState(null);
55	  const [showCategPanel, setShowCategPanel] = useState(false);
56	  const [loading, setLoading] = useState(true);
57	  const [erro, setErro] = useState(null);
58	  const [showModal, setShowModal] = useState(false);
59	  const [editando, setEditando] = useState(null);
60	  const [form, setForm] = useState(EMPTY_FORM);
61	  const [salvando, setSalvando] = useState(false);
62	  const [deletando, setDeletando] = useState(null);
63	  const [adicionandoCarrossel, setAdicionandoCarrossel] = useState(null);
64	  const [busca, setBusca] = useState('');
65	  const [filtroCategoria, setFiltroCategoria] = useState('');
66	  const [filtroStatus, setFiltroStatus] = useState('todos');
67	  const [filtroEstoque, setFiltroEstoque] = useState('todos');
68	  const [showImportModal, setShowImportModal] = useState(false);
69	  const [showFormatoModal, setShowFormatoModal] = useState(false);
70	  const [jsonImport, setJsonImport] = useState('');
71	  const [erroImport, setErroImport] = useState(null);
72	  const [importando, setImportando] = useState(false);
73	  const [resultadoImport, setResultadoImport] = useState(null);
74	  const [copiadoFormato, setCopiadoFormato] = useState(false);
75	
76	  const carregar = () => {
77	    setLoading(true);
78	    Promise.all([getMeusProdutos(), getMinhasCategorias(), getCategoriasGlobais(), getTagsPublicas()])
79	      .then(([p, mine, global, tagsResp]) => {
80	        setProdutos(p.produtos ?? []);
81	        setCategorias(mine.categorias ?? []);
82	        setCategoriasGlobais(global.categorias ?? []);
83	        // Só tags manuais (is_auto=false) — restaurante pode atribuir
84	        setTagsDisponiveis((tagsResp.tags ?? []).filter((t) => !t.is_auto));
85	      })
86	      .catch((e) => setErro(e.message))
87	      .finally(() => setLoading(false));
88	  };
89	
90	  useEffect(() => { carregar(); }, []);
91	  useEffect(() => { if (tipoRestaurante) listarImpressoras().then(setImpressoras).catch(() => {}); }, [tipoRestaurante]);
92	
93	  const abrirNovo = () => {
94	    setEditando(null);
95	    setForm(EMPTY_FORM);
96	    setShowModal(true);
97	  };
98	
