100	    setEditando(p);
101	    setForm({
102	      name: p.name ?? '',
103	      description: p.description ?? '',
104	      price: p.price != null ? String(p.price) : '',
105	      preco_promo: p.preco_promo != null ? String(p.preco_promo) : '',
106	      image_url: p.image_url ?? '',
107	      category_id: p.category_id != null ? String(p.category_id) : '',
108	      tags: Array.isArray(p.tags) ? p.tags : [],
109	      destaque: p.destaque ?? false,
110	      impressora_id: p.impressora_id != null ? String(p.impressora_id) : '',
111	      quantidade_estoque: p.quantidade_estoque != null ? String(p.quantidade_estoque) : '0',
112	      preco_custo: p.preco_custo != null ? String(p.preco_custo) : '',
113	      quantidade_minima: p.quantidade_minima != null ? String(p.quantidade_minima) : '0',
114	    });
115	    setShowModal(true);
116	  };
117	
118	  const handleCriarCategoria = async (e) => {
119	    e.preventDefault();
120	    if (!novaCategoria.trim()) return;
121	    setCriandoCateg(true);
122	    try {
123	      const nova = await criarCategoria(novaCategoria.trim());
124	      setCategorias((prev) => [...prev, nova].sort((a, b) => a.name.localeCompare(b.name)));
125	      setNovaCategoria('');
126	    } catch (err) {
127	      alert(err.message);
128	    } finally {
129	      setCriandoCateg(false);
130	    }
131	  };
132	
133	  const handleDeletarCategoria = async (cat) => {
134	    if (!window.confirm(`Deletar categoria "${cat.name}"? Os produtos ligados perderão esta categoria.`)) return;
135	    setDeletandoCateg(cat.id);
136	    try {
137	      await deletarCategoria(cat.id);
138	      setCategorias((prev) => prev.filter((c) => c.id !== cat.id));
139	    } catch (err) {
140	      alert(err.message);
141	    } finally {
142	      setDeletandoCateg(null);
143	    }
144	  };
145	
146	  const fecharModal = () => {
147	    setShowModal(false);
148	    setEditando(null);
149	    setForm(EMPTY_FORM);
150	  };
151	
152	  const abrirImportModal = () => {
153	    setJsonImport('');
154	    setErroImport(null);
155	    setResultadoImport(null);
156	    setShowImportModal(true);
157	  };
158	
159	  const fecharImportModal = () => {
160	    setShowImportModal(false);
161	    if (resultadoImport?.importados > 0) carregar();
162	  };
163	
164	  const handleArquivoJson = (e) => {
165	    const file = e.target.files?.[0];
166	    if (!file) return;
167	    const reader = new FileReader();
168	    reader.onload = () => setJsonImport(String(reader.result ?? ''));
169	    reader.readAsText(file);
170	  };
171	
172	  const copiarFormato = () => {
173	    navigator.clipboard?.writeText(JSON_FORMATO_EXEMPLO);
174	    setCopiadoFormato(true);
175	    setTimeout(() => setCopiadoFormato(false), 2000);
176	  };
177	
178	  const handleImportar = async () => {
179	    setErroImport(null);
180	    let lista;
181	    try {
182	      lista = JSON.parse(jsonImport);
183	    } catch {
184	      setErroImport('JSON inválido. Confira o formato (veja o link "Ver formato padrão do JSON").');
185	      return;
186	    }
187	    if (!Array.isArray(lista) || lista.length === 0) {
188	      setErroImport('O JSON precisa ser uma lista com pelo menos um produto.');
