74	                  <span className="text-sm font-bold text-[#18181B] w-5 text-center">{qtd}</span>
75	                  <button onClick={() => onAdicionar(produto, precoFinal, +1)}
76	                    className="w-7 h-7 bg-[#FF441F] rounded-full font-bold text-white flex items-center justify-center hover:bg-[#E63A19] text-base">+</button>
77	                </div>
78	              )}
79	            </div>
80	          ) : (
81	            <span className="text-xs text-[#71717A] bg-[#F4F4F5] px-2 py-1 rounded-lg">Indisponível</span>
82	          )}
83	        </div>
84	      </div>
85	
86	      {produto.image_url && (
87	        <div className="relative flex-shrink-0 w-28 h-24">
88	          <img src={produto.image_url} alt={produto.name} className="w-full h-full object-cover rounded-xl" />
89	          {indisponivel && (
90	            <div className="absolute inset-0 bg-white/60 rounded-xl flex items-center justify-center">
91	              <span className="text-[10px] text-[#71717A] font-semibold">Indisponível</span>
92	            </div>
93	          )}
94	        </div>
95	      )}
96	    </motion.div>
97	  );
98	};
99	
100	/* ── Carrossel de combos ativos (topo da loja) ────────────────────── */
101	const ComboCarrosselCard = ({ combo, onAdicionar, restauranteFechado }) => {
102	  const temPromo = combo.preco_promo != null;
103	  const precoFinal = temPromo ? combo.preco_promo : combo.price;
104	
105	  return (
106	    <button
107	      onClick={() => !restauranteFechado && onAdicionar(combo, precoFinal)}
108	      disabled={restauranteFechado}
109	      className={`flex-shrink-0 w-36 sm:w-40 bg-white rounded-2xl border overflow-hidden text-left relative ${
110	        restauranteFechado ? 'border-[#E4E4E7] opacity-60' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/30'
111	      }`}
112	    >
113	      <div className="relative h-28 bg-[#F4F4F5]">
114	        {combo.image_url
115	          ? <img src={combo.image_url} alt={combo.name} className="w-full h-full object-cover" />
116	          : <div className="w-full h-full flex items-center justify-center"><Icon name="Package" size={28} className="text-[#E4E4E7]" /></div>}
117	        <span className="absolute top-2 left-2 text-[9px] font-bold bg-[#FF441F] text-white px-1.5 py-0.5 rounded-full shadow">COMBO</span>
118	      </div>
