128	};
129	
130	const ComboCarrossel = ({ combos, onAdicionar, restauranteFechado }) => {
131	  const scrollRef = useRef(null);
132	  const scroll = (dir) => {
133	    if (scrollRef.current) scrollRef.current.scrollBy({ left: dir * 200, behavior: 'smooth' });
134	  };
135	
136	  return (
137	    <div className="relative">
138	      <button onClick={() => scroll(-1)}
139	        className="absolute left-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -ml-4 hidden sm:flex">
140	        <Icon name="ChevronLeft" size={16} className="text-[#27272A]" />
141	      </button>
142	      <div ref={scrollRef} className="flex gap-3 overflow-x-auto pb-1" style={{ scrollbarWidth: 'none' }}>
143	        {combos.map((c) => (
144	          <ComboCarrosselCard key={c.id} combo={c} onAdicionar={onAdicionar} restauranteFechado={restauranteFechado} />
145	        ))}
146	      </div>
147	      <button onClick={() => scroll(1)}
148	        className="absolute right-0 top-1/2 -translate-y-1/2 z-10 w-8 h-8 bg-white border border-[#E4E4E7] rounded-full shadow flex items-center justify-center hover:bg-[#F4F4F5] -mr-4 hidden sm:flex">
149	        <Icon name="ChevronRight" size={16} className="text-[#27272A]" />
150	      </button>
151	    </div>
152	  );
153	};
154	
155	/* ── Conteúdo do carrinho (mobile + desktop) ─────────────────────── */
156	const CarrinhoConteudo = ({ carrinho, onAdicionar, onFechar, onCheckout }) => {
157	  const totalItens = carrinho.reduce((acc, i) => acc + i.qtd, 0);
158	  const totalValor = carrinho.reduce((acc, i) => acc + i.price * i.qtd, 0);
159	
160	  return (
161	    <>
162	      <div className="flex items-center justify-between px-5 pt-4 pb-3 border-b border-[#E4E4E7] flex-shrink-0">
163	        <h3 className="font-bold text-[#18181B] text-base">
164	          Carrinho <span className="text-[#FF441F]">({totalItens})</span>
165	        </h3>
166	        {onFechar && (
167	          <button onClick={onFechar} className="p-1.5 hover:bg-[#F4F4F5] rounded-lg">
168	            <Icon name="X" size={18} className="text-[#71717A]" />
169	          </button>
170	        )}
171	      </div>
172	
173	      <div className="flex-1 overflow-y-auto px-5 py-4 space-y-3">
174	        <AnimatePresence>
175	          {carrinho.map((item) => (
176	            <motion.div key={item.id} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 16 }}
177	              className="flex items-center gap-3">
178	              {item.image_url && (
179	                <img src={item.image_url} alt={item.name} className="w-12 h-12 rounded-xl object-cover flex-shrink-0" />
180	              )}
181	              <div className="flex-1 min-w-0">
182	                <p className="text-sm font-medium text-[#18181B] truncate">{item.name}</p>
183	                <p className="text-xs text-[#71717A]">{fmt(item.price)}</p>
184	              </div>
185	              <div className="flex items-center gap-1.5 flex-shrink-0">
186	                <button onClick={() => onAdicionar(item, item.price, -1)}
187	                  className="w-6 h-6 bg-[#F4F4F5] rounded-full text-sm font-bold text-[#27272A] flex items-center justify-center">−</button>
188	                <span className="text-sm font-bold text-[#18181B] w-4 text-center">{item.qtd}</span>
189	                <button onClick={() => onAdicionar(item, item.price, +1)}
190	                  className="w-6 h-6 bg-[#FF441F] rounded-full text-sm font-bold text-white flex items-center justify-center">+</button>
191	              </div>
192	            </motion.div>
193	          ))}
194	        </AnimatePresence>
195	      </div>
196	
197	      <div className="px-5 py-4 border-t border-[#E4E4E7] flex-shrink-0">
198	        <div className="flex justify-between text-sm mb-1">
199	          <span className="text-[#71717A]">Subtotal</span>
200	          <span className="font-medium text-[#27272A]">{fmt(totalValor)}</span>
