214	
215	/* ── Drawer mobile (bottom sheet) ────────────────────────────────── */
216	const CarrinhoMobile = ({ carrinho, onAdicionar, onFechar, onCheckout }) => (
217	  <>
218	    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
219	      onClick={onFechar} className="fixed inset-0 bg-black/40 z-40 lg:hidden" />
220	    <motion.div
221	      initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
222	      transition={{ type: 'spring', damping: 28, stiffness: 300 }}
223	      className="fixed bottom-0 left-0 right-0 z-50 bg-white rounded-t-3xl shadow-2xl lg:hidden max-h-[82vh] flex flex-col"
224	    >
225	      <div className="w-10 h-1 bg-[#E4E4E7] rounded-full mx-auto mt-3 mb-1 flex-shrink-0" />
226	      <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={onFechar} onCheckout={onCheckout} />
227	    </motion.div>
228	  </>
229	);
230	
231	/* ── Sidebar desktop ─────────────────────────────────────────────── */
232	const CarrinhoDesktop = ({ carrinho, onAdicionar, onCheckout }) => (
233	  <aside className="hidden lg:block w-80 xl:w-96 flex-shrink-0">
234	    <div className="sticky top-28 bg-white rounded-2xl border border-[#E4E4E7] shadow-sm overflow-hidden flex flex-col max-h-[calc(100vh-120px)]">
235	      {carrinho.length === 0 ? (
236	        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
237	          <Icon name="ShoppingCart" size={44} className="text-[#E4E4E7] mb-3" />
238	          <p className="text-sm font-semibold text-[#27272A]">Carrinho vazio</p>
239	          <p className="text-xs text-[#71717A] mt-1">Adicione itens do cardápio</p>
240	        </div>
241	      ) : (
242	        <CarrinhoConteudo carrinho={carrinho} onAdicionar={onAdicionar} onFechar={null} onCheckout={onCheckout} />
243	      )}
244	    </div>
245	  </aside>
246	);
247	
248	/* ── Componente principal ────────────────────────────────────────── */
249	const RestauranteCatalogo = ({ dadosPreCarregados } = {}) => {
250	  const { slug: slugParam } = useParams();
251	  const navigate = useNavigate();
252	  const { isAuthenticated, isRestaurantOwner, isAdmin } = useAuth();
253	  const [data, setData] = useState(dadosPreCarregados ?? null);
254	  const [loading, setLoading] = useState(!dadosPreCarregados);
255	  const [erro, setErro] = useState(null);
256	  const [carrinho, setCarrinho] = useState([]);
257	  const [catAtiva, setCatAtiva] = useState('todos');
258	  const [carrinhoAberto, setCarrinhoAberto] = useState(false);
259	
260	  // Quando aberto via domínio customizado (dadosPreCarregados vindo do HomeRouter),
261	  // não existe :slug na URL — o fetch abaixo é pulado, os dados já chegam prontos.
262	  useEffect(() => {
263	    if (dadosPreCarregados) return;
264	    setLoading(true);
265	    getCardapioPorSlug(slugParam)
266	      .then((d) => {
267	        setData(d);
268	        setCatAtiva('todos');
269	      })
270	      .catch((e) => setErro(e.message))
271	      .finally(() => setLoading(false));
272	  }, [slugParam, dadosPreCarregados]);
273	
274	  // Slug efetivo pro checkout: vem da URL em /r/:slug, ou do próprio payload
275	  // quando a loja foi aberta pelo domínio customizado (sem slug na URL).
276	  const slug = slugParam ?? data?.restaurante?.slug;
277	
278	  // Combo e produto têm sequências de id independentes — pode colidir (combo #5 e
279	  // produto #5), então a chave do carrinho precisa considerar o tipo junto do id.
280	  const chaveCarrinho = (item) => `${item.tipo === 'combo' ? 'combo' : 'produto'}-${item.id}`;
281	
282	  const altCarrinho = (produto, preco, delta = 1) => {
283	    setCarrinho((prev) => {
284	      const chave = chaveCarrinho(produto);
285	      const idx = prev.findIndex((i) => chaveCarrinho(i) === chave);
286	      if (idx >= 0) {
287	        const novo = [...prev];
288	        const novaQtd = novo[idx].qtd + delta;
289	        if (novaQtd <= 0) { novo.splice(idx, 1); return novo; }
290	        novo[idx] = { ...novo[idx], qtd: novaQtd };
291	        return novo;
292	      }
293	      if (delta < 0) return prev;
294	      return [...prev, { ...produto, price: preco, qtd: 1 }];
295	    });
296	  };
297	
298	  const qtdNoCarrinho = (produto) => carrinho.find((i) => chaveCarrinho(i) === chaveCarrinho(produto))?.qtd ?? 0;
299	  const totalItens = carrinho.reduce((acc, i) => acc + i.qtd, 0);
300	  const totalValor = carrinho.reduce((acc, i) => acc + i.price * i.qtd, 0);
301	
302	  const irParaCheckout = () => {
303	    const restauranteId = data?.restaurante?.id;
304	    const freteMotoboy = parseFloat(data?.restaurante?.frete_motoboy ?? 0);
305	    if (!isAuthenticated()) {
306	      sessionStorage.setItem('pending_cart', JSON.stringify({ carrinho, restauranteSlug: slug, restauranteId, freteMotoboy }));
307	      navigate('/customer-registration-login', { state: { from: '/shopping-cart-checkout' } });
308	      return;
309	    }
310	    navigate('/shopping-cart-checkout', { state: { carrinho, restauranteSlug: slug, restauranteId, freteMotoboy } });
311	  };
312	
313	  if (loading) return (
314	    <div className="min-h-screen bg-[#F4F4F5]">
315	      <div className="h-64 bg-gradient-to-br from-[#FF441F] to-[#FF7A00] animate-pulse" />
316	      <div className="max-w-screen-xl mx-auto px-4 py-6 grid grid-cols-1 xl:grid-cols-2 gap-3">
317	        {[...Array(6)].map((_, i) => <SkeletonProduto key={i} />)}
318	      </div>
319	    </div>
320	  );
321	
322	  if (erro) return (
323	    <div className="min-h-screen flex flex-col items-center justify-center bg-[#F4F4F5] p-6 text-center">
324	      <Icon name="Store" size={56} className="text-[#E4E4E7] mb-4" />
325	      <p className="text-lg font-semibold text-[#27272A]">Restaurante não encontrado</p>
326	      <p className="text-sm text-[#71717A] mt-1">{erro}</p>
327	      <button onClick={() => navigate(-1)} className="mt-6 px-4 py-2.5 bg-[#FF441F] text-white rounded-xl text-sm font-semibold">Voltar</button>
328	    </div>
329	  );
330	
331	  const { restaurante, cardapio, destaques, promos, combos } = data;
332	  const ap = restaurante.aparencia ?? {};
333	
334	  const tabs = [
335	    { id: 'todos', label: 'Todos' },
336	    ...(destaques?.length ? [{ id: 'destaques', label: '⭐ Destaques' }] : []),
337	    ...(promos?.length ? [{ id: 'promos', label: '🔥 Promoções' }] : []),
338	    ...(combos?.length ? [{ id: 'combos', label: '🍱 Combos' }] : []),
339	    ...cardapio.map((c) => ({ id: c.id, label: c.name })),
